with FilteredAccounts as (select * from accounts where customer_id in (15, 22, 28, 31)), accounts_stats as (select case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, count(case when account_type = 'CREDIT' then 1 end) as credit_count from FilteredAccounts group by case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end) select * from accounts_stats where credit_count < 7 order by credit_count;
